// #db5c46 «BUG · עמודת הכותרת בשורות הרשימה מצטמצמת ל-27pt בזום 200% ב-/lessons וב-/tehilim» — עבר QA 08.11 (веб 195 px + Android).
//   AC: «בזום 200% שורת רשימה ב-/lessons וב-/tehilim מציגה את כותרתה ברוחב שמאפשר קריאה רציפה, ולא נשברת כל שתיים-שלוש אותיות».
// Факт 08.11 (Pixel 6, wm density 840): строки уроков и תהילים читаются, переносы между словами (скрины 2026-11-08_db5c46_android_*).
// Мера «ширины для чтения»: текст строки ≥ 35% ширины экрана (баг — ~27pt из ~205dp ≈ 13%), строк не больше, чем слов.
// Кейс: .qa/tests/zoom-200/Z2-02-list-row-titles.md. Только просмотр. Плотность возвращается в after().
import { driver, expect } from '@wdio/globals';
import { goTab } from '../../helpers/nav.ts';
import { tapLabel } from '../../helpers/ui.ts';
import { goHome, nodes, type UiNode } from '../_lib/readiness-1910.ts';
import { skipWith } from '../_lib/app-0710.ts';
import { zoomOn, zoomOff, textNode, insideScreenX, linesAtZoom, wordCount, saveShot } from '../_lib/app-0911.ts';

const LESSON = 'שיעור בדיקה — לא תוכן מאושר';   // урок QA из tl-01
const MIN_SHARE = 0.35;

async function openLessons() {
  await goHome(); await goTab('תפילות');
  await tapLabel('שיעורי תורה, השיעורים הזמינים לקריאה');
}
/** Список תהילים — под вкладкой «ברכות» (после #4cfbf19e), запасной — «תהילים». */
async function openTehilimList() {
  await goHome(); await goTab('ברכות');
  if (!(await nodes()).some((n) => n.label === 'פרקי אבות')) await goTab('תהילים');
  await textNode('פרקי אבות');
}
/** Многословные тексты строк в средней части экрана (без шапки, поиска и нижней навигации). */
async function rowTexts(): Promise<UiNode[]> {
  const { height } = await driver.getWindowSize();
  return (await nodes()).filter((n) => /TextView/.test(n.type) && n.visible && n.y > height * 0.3 && n.y + n.h < height * 0.85
    && wordCount(n.label) >= 2 && !/חיפוש/.test(n.label));
}

describe('09.11 — зум 200% (Android): колонка заголовка в строках списков (#db5c46)', () => {
  before(function () { if (!driver.isAndroid) skipWith(this, 'зум через wm density — только Android'); });
  after(async () => { if (driver.isAndroid) await zoomOff(); });

  it('Z2-02 При wm density 840 заголовок строки «שיעורי תורה» и строки списка תהילים шире 35% экрана и не рвутся по 2–3 буквы #db5c46 @android @prod-safe @manual-check', async () => {
    await openLessons();
    const normalLesson = await textNode(LESSON);

    await goHome();
    await zoomOn();
    const { width } = await driver.getWindowSize();

    // 1. Уроки.
    await openLessons();
    const z = await textNode(LESSON);
    await saveShot('q28-lessons-row.png');
    console.log(`[Q-28] урок: ${z.w}×${z.h} из ширины ${width}; ~${linesAtZoom(z.h, normalLesson.h)} строк`);
    expect(z.w).toBeGreaterThanOrEqual(width * MIN_SHARE);
    expect(await insideScreenX(z)).toBe(true);
    expect(linesAtZoom(z.h, normalLesson.h)).toBeLessThanOrEqual(wordCount(LESSON));

    // 2. תהילים.
    await openTehilimList();
    const rows = await rowTexts();
    await saveShot('q28-tehilim-rows.png');
    expect(rows.length).toBeGreaterThan(0);
    for (const r of rows) {
      console.log(`[Q-28] תהילים «${r.label.slice(0, 30)}»: ширина ${r.w}`);
      expect(r.w).toBeGreaterThanOrEqual(width * MIN_SHARE);
      expect(await insideScreenX(r)).toBe(true);
    }
  });
});
